The case where the wallet may be a contract address. If the asset is an ERC-20 token, but the wallet is a contract address and the contract does not have the logic to handle ERC-20 tokens, then sending ERC-20 tokens to this contract address may result in the permanent loss of the tokens.

## Proof of Concept
wallet is a contract address and the contract does not have the logic to handle ERC-20 tokens, then sending ERC-20 tokens to this contract address may result in the permanent loss of the tokens

## Tools Used
Remix IDE
## Recommended Mitigation Steps
In order to prevent the loss of ERC20, an additional verification step is added.
```solidity
function transferToCustody(address wallet, address asset, uint256 amount) external nonReentrant onlyRole(MINTER_ROLE) {
    require(wallet != address(0) && !isContract(wallet), "Invalid wallet address");

    if (asset == NATIVE_TOKEN) {
        (bool success,) = wallet.call{value: amount}("");
        if (!success) revert TransferFailed();
    } else {
        IERC20(asset).safeTransfer(wallet, amount);
    }
    emit CustodyTransfer(wallet, asset, amount);
}

function isContract(address addr) internal view returns (bool) {
    uint size;
    assembly {
        size := extcodesize(addr)
    }
    return size > 0;
}

```


